            data-aos='fade-left'
            data-aos-offset='300'
            data-aos-easing='ease-in-sine'
          >
            <h1 style={{ fontSize: '28px', fontWeight: '500' , textAlign:"center"}}>
              What Can Monitor?
            </h1>
            <img
              className=' '
              src={monitorTransformerImg}
              alt='interconnect billing'
              style={{ width: '100%', objectFit: 'contain' }}
            />

            {/* {data.map((item, index) => {
              return (
